svg.script:
const site = document.getElementById("site");
const msg = document.getElementById("msg");
fetch(new URL("index.html", location.href))
  .then(r => { if(!r.ok) throw new Error("HTTP " + r.status); return r.text(); })
  .then(html => {
    site.srcdoc = html;
    site.addEventListener("load", () => { msg.remove(); site.focus(); }, { once: true });
  })
  .catch(e => { msg.textContent = "couldn't load the site (" + e.message + ")"; msg.setAttribute("fill", "#f38ba8"); });
// mirror the site's page title onto the browser tab
const title = document.querySelector("title");
setInterval(() => { try { const t = site.contentDocument.title; if(t && title.textContent !== t) title.textContent = t; } catch {} }, 800);
